function GardenTrowelHolsterMaker.init() GardenTrowelHolsterMaker.ironStock=10; GardenTrowelHolsterMaker.bronzeStock=8; GardenTrowelHolsterMaker.woodStock=12; GardenTrowelHolsterMaker.leatherStock=18; GardenTrowelHolsterMaker.silverStock=8; GardenTrowelHolsterMaker.goldStock=6; GardenTrowelHolsterMaker.jewelStock=4; GardenTrowelHolsterMaker.pearlStock=4; GardenTrowelHolsterMaker.productStock={}; GardenTrowelHolsterMaker.buildings={}; GardenTrowelHolsterMaker.maker=nil; GardenTrowelHolsterMaker.activeMaking={}; GardenTrowelHolsterMaker.totalProducts=0; GardenTrowelHolsterMaker.dayTimer=0; print("[GardenTrowelHolsterMaker] Royal Garden Trowel Holster Maker System initialized (6 products, 4 buildings)") end
function GardenTrowelHolsterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenTrowelHolsterMaker.maker={name=n or ("Nositelj "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nositelj najet: %s (spretnost: %d)",GardenTrowelHolsterMaker.maker.name,s),"success") end; return true end
function GardenTrowelHolsterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenTrowelHolsterMaker.build(id) local ok,e=GardenTrowelHolsterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenTrowelHolsterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
