function GardenTrowelHolsterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenTrowelHolsterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenTrowelHolsterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenTrowelHolsterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenTrowelHolsterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenTrowelHolsterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenTrowelHolsterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenTrowelHolsterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenTrowelHolsterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenTrowelHolsterMaker.buildings==0 then return false,"Potrebna nositeljska delavnica" end; if not GardenTrowelHolsterMaker.maker then return false,"Potreben nositelj" end; return true end
function GardenTrowelHolsterMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenTrowelHolsterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenTrowelHolsterMaker.ironStock=GardenTrowelHolsterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenTrowelHolsterMaker.bronzeStock=GardenTrowelHolsterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenTrowelHolsterMaker.woodStock=GardenTrowelHolsterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenTrowelHolsterMaker.leatherStock=GardenTrowelHolsterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenTrowelHolsterMaker.silverStock=GardenTrowelHolsterMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenTrowelHolsterMaker.goldStock=GardenTrowelHolsterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenTrowelHolsterMaker.jewelStock=GardenTrowelHolsterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenTrowelHolsterMaker.pearlStock=GardenTrowelHolsterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenTrowelHolsterMaker.maker then t=math.max(1,t-math.floor(GardenTrowelHolsterMaker.maker.skill/13)) end; table.insert(GardenTrowelHolsterMaker.activeMaking,{id="gardentrowelholster_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenTrowelHolsterMaker.completeMaking(m) local q=1.0+(GardenTrowelHolsterMaker.getQualityBonus()/100); if GardenTrowelHolsterMaker.maker then q=q+(GardenTrowelHolsterMaker.maker.skill/140) end; q=math.min(2.5,q); GardenTrowelHolsterMaker.productStock[m.productType]=(GardenTrowelHolsterMaker.productStock[m.productType] or 0)+m.quantity; GardenTrowelHolsterMaker.totalProducts=GardenTrowelHolsterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenTrowelHolsterMaker.maker then GardenTrowelHolsterMaker.maker.itemsMade=GardenTrowelHolsterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenTrowelHolsterMaker.maker.skill=math.min(100,GardenTrowelHolsterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nositev izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardentrowelholster.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenTrowelHolsterMaker.update(dt) if not _G.state then return end; GardenTrowelHolsterMaker.dayTimer=GardenTrowelHolsterMaker.dayTimer+dt; if GardenTrowelHolsterMaker.dayTimer>=30 then GardenTrowelHolsterMaker.dayTimer=0; for i=#GardenTrowelHolsterMaker.activeMaking,1,-1 do local m=GardenTrowelHolsterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenTrowelHolsterMaker.completeMaking(m); table.remove(GardenTrowelHolsterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenTrowelHolsterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenTrowelHolsterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
